<script setup>
import { reactive, ref, watch } from 'vue';
import ProgressBar from './ProgressBar.vue'; import SelectCard from './SelectCard.vue'; import FormNavigation from './FormNavigation.vue'; import DatePicker from './DatePicker.vue'; import { submitOnboarding } from '../api';
const config=window.clientOnboarding,steps=['Business','Website','Pages','Content','Features','Hosting','Final'],current=ref(0),review=ref(false),success=ref(false),submitting=ref(false),serverError=ref(''),errors=reactive({}),files=ref([]),sitemapFile=ref(null);
const blank={company_name:'',contact_name:'',email:'',phone:'',business_description:'',services:'',existing_website:'',website_url:'',website_type:[],website_type_other:'',primary_action:'',primary_action_other:'',language_count:1,languages:['Thai'],pages:[],custom_pages:[],content_status:'',assets:[],assets_other:'',references:[{url:'',notes:''}],features:[],features_other:'',domain_status:'',domain:'',hosting_status:'',hosting_choice:'',target_launch:'',no_date:false,notes:'',website:'',started_at:config.startedAt};
let saved={};try{saved=JSON.parse(localStorage.getItem('client_onboarding_draft'))||{}}catch(e){}const form=reactive({...blank,...saved,started_at:config.startedAt});watch(form,v=>localStorage.setItem('client_onboarding_draft',JSON.stringify(v)),{deep:true});
const types=['Company / Business Website','Showcase Services','Portfolio / Projects','Ecommerce','Booking / Appointment','Lead Generation','Other'],actions=['Contact us','Call us','Send an enquiry','Book an appointment','Buy a product','Request a quote','Visit a location','Other'],pageOptions=['Home','About','Services','Products','Portfolio / Projects','Blog / News','FAQ','Contact','Other'],assetOptions=['Logo','Brand colours / guidelines','Images','Videos','Fonts','Company profile / brochure','Other'],featureOptions=['Contact Form','WhatsApp','LINE','Google Map','Booking / Appointment','Ecommerce','Online Payment','Member Login','Blog / News','Multilingual','Live Chat','Other'];
function required(key,label){if(!form[key])errors[key]=`${label} is required.`}function validate(){Object.keys(errors).forEach(k=>delete errors[k]);if(current.value===0){required('company_name','Company name');required('contact_name','Contact name');required('email','Email');required('business_description','Business description');if(form.email&&!/^\S+@\S+\.\S+$/.test(form.email))errors.email='Enter a valid email.';if(form.existing_website==='Yes')required('website_url','Website URL')}if(current.value===1&&form.languages.some(x=>!String(x||'').trim()))errors.languages='Please enter every website language.';if(Object.keys(errors).length){requestAnimationFrame(()=>document.querySelector('.error input,.error textarea')?.focus());return false}return true}
function next(){if(!validate())return;if(current.value<steps.length-1)current.value++;else review.value=true;window.scrollTo({top:0,behavior:'smooth'})}function back(){if(review.value)review.value=false;else if(current.value>0)current.value--;window.scrollTo({top:0,behavior:'smooth'})}function go(i){current.value=i;review.value=false;window.scrollTo({top:0,behavior:'smooth'})}
function syncLanguages(){form.language_count=Math.min(10,Math.max(1,Number(form.language_count)||1));while(form.languages.length<form.language_count)form.languages.push('');form.languages=form.languages.slice(0,form.language_count)}
function addReference(){if(form.references.length<3)form.references.push({url:'',notes:''})}function pickFiles(e){files.value=[...files.value,...Array.from(e.target.files)].slice(0,10);e.target.value=''}function removeFile(i){files.value.splice(i,1)}function pickSitemap(e){sitemapFile.value=e.target.files?.[0]||null;e.target.value=''}
async function submit(){submitting.value=true;serverError.value='';try{await submitOnboarding(form,files.value,sitemapFile.value);localStorage.removeItem('client_onboarding_draft');success.value=true}catch(e){serverError.value=e.message;Object.assign(errors,e.fields||{})}finally{submitting.value=false}}
const val=(v)=>Array.isArray(v)?(v.join(', ')||'—'):(v||'—');
</script>
<template><div class="shell"><header class="brand"><img v-if="config.logo" :src="config.logo" alt=""><span v-else class="mark">CO</span><div><strong>{{ config.title }}</strong><small>Project discovery</small></div></header><div v-if="success" class="success"><span>✓</span><h1>Thank you!</h1><p>We've received your project details. We'll review everything and get in touch if we need anything else.</p></div><div v-else class="app-layout"><section class="onboarding-hero"><div><p>Website project onboarding</p><h1>{{ config.title }}</h1><span>{{ config.intro }}</span></div><b>{{ review ? 'Ready to submit' : `Step ${current + 1} of ${steps.length}` }}</b></section><ProgressBar :steps="steps" :current="current" :review="review" @go="go"/><main class="form-card"><div v-if="!review">
<section v-if="current===0"><p class="eyebrow">Business details</p><h1>Tell us about your business</h1><p class="lede">Start with the essentials so we know who we're building for.</p><div class="fields two"><label :class="{error:errors.company_name}">Company / Brand Name *<input v-model="form.company_name"><small>{{ errors.company_name }}</small></label><label :class="{error:errors.contact_name}">Contact Name *<input v-model="form.contact_name"><small>{{ errors.contact_name }}</small></label><label :class="{error:errors.email}">Email Address *<input type="email" v-model="form.email"><small>{{ errors.email }}</small></label><label>Phone Number<input type="tel" v-model="form.phone"></label></div><label :class="{error:errors.business_description}">What does your business do? *<textarea rows="4" v-model="form.business_description"></textarea><em>Give us a short overview of your business and what you offer.</em><small>{{ errors.business_description }}</small></label><label>Main Products or Services<textarea rows="3" v-model="form.services"></textarea></label><fieldset><legend>Do you currently have a website?</legend><div class="choices"><SelectCard v-for="x in ['Yes','No']" :value="x" v-model="form.existing_website"/></div></fieldset><label v-if="form.existing_website==='Yes'" :class="{error:errors.website_url}">Website URL *<input type="url" placeholder="https://example.com" v-model="form.website_url"><small>{{ errors.website_url }}</small></label></section>
<section v-if="current===1"><p class="eyebrow">Website goals</p><h1>What do you need from your website?</h1><fieldset><legend>Website purpose</legend><div class="choices grid"><SelectCard v-for="x in types" :value="x" multiple v-model="form.website_type"/></div></fieldset><label v-if="form.website_type.includes('Other')">Describe the purpose<input v-model="form.website_type_other"></label><fieldset><legend>What is the main action you want visitors to take?</legend><div class="choices grid"><SelectCard v-for="x in actions" :value="x" v-model="form.primary_action"/></div></fieldset><label v-if="form.primary_action==='Other'">Main action<input v-model="form.primary_action_other"></label><fieldset class="language-panel" :class="{error:errors.languages}"><legend>Website languages</legend><p class="field-help">Languages affect project scope and pricing. Tell us exactly how many versions the website needs.</p><label>How many languages?<input class="number-input" type="number" min="1" max="10" v-model.number="form.language_count" @input="syncLanguages"></label><div class="fields two language-fields"><label v-for="n in form.language_count" :key="n">Language {{ n }} *<input :placeholder="n===1?'e.g. Thai':'e.g. English'" v-model="form.languages[n-1]"></label></div><small>{{ errors.languages }}</small></fieldset></section>
<section v-if="current===2"><p class="eyebrow">Site structure</p><h1>Which pages do you need?</h1><p class="lede">Choose everything you expect to include. This can evolve later.</p><div class="choices grid"><SelectCard v-for="x in pageOptions" :value="x" multiple v-model="form.pages"/></div><label v-if="form.pages.includes('Other')">Custom pages (one per line)<textarea rows="4" :value="form.custom_pages.join('\n')" @input="form.custom_pages=$event.target.value.split('\n').filter(Boolean)"></textarea></label><div class="upload sitemap-upload"><div><strong>Already have a sitemap?</strong><p>Upload it here and we’ll use it to confirm the page count and project scope.</p></div><label class="button ghost">Choose sitemap<input hidden type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.csv,.jpg,.jpeg,.png" @change="pickSitemap"></label><p class="upload-hint">PDF, Word, Excel, CSV, JPG or PNG. Maximum 10MB.</p><div v-if="sitemapFile" class="selected-file"><span>{{ sitemapFile.name }}</span><button type="button" @click="sitemapFile=null">Remove</button></div></div></section>
<section v-if="current===3"><p class="eyebrow">Content & assets</p><h1>Content & brand assets</h1><fieldset><legend>Is your website content ready?</legend><div class="choices"><SelectCard v-for="x in ['Yes, everything is ready','Some content is ready','Not ready yet']" :value="x" v-model="form.content_status"/></div></fieldset><fieldset><legend>Which assets do you already have?</legend><div class="choices grid"><SelectCard v-for="x in assetOptions" :value="x" multiple v-model="form.assets"/></div></fieldset><label v-if="form.assets.includes('Other')">Other assets<input v-model="form.assets_other"></label><div class="upload"><label class="button ghost">Choose files<input hidden type="file" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.doc,.docx,.zip,.svg" @change="pickFiles"></label><p>JPG, PNG, WebP, PDF, Word, ZIP or SVG. Up to 10MB each.</p><ul><li v-for="(file,i) in files">{{ file.name }} <button type="button" @click="removeFile(i)">Remove</button></li></ul></div><fieldset><legend>Do you have any websites you like?</legend><div class="reference" v-for="(ref,i) in form.references"><label>Website {{ i+1 }}<input type="url" placeholder="https://" v-model="ref.url"></label><label>What do you like about it?<textarea rows="2" v-model="ref.notes"></textarea></label></div><button v-if="form.references.length<3" type="button" class="text-button" @click="addReference">+ Add another reference</button></fieldset></section>
<section v-if="current===4"><p class="eyebrow">Functionality</p><h1>What features does the website need?</h1><div class="choices grid"><SelectCard v-for="x in featureOptions" :value="x" multiple v-model="form.features"/></div><label v-if="form.features.includes('Other')">Please describe the feature<textarea rows="3" v-model="form.features_other"></textarea></label></section>
<section v-if="current===5"><p class="eyebrow">Technical setup</p><h1>Domain & hosting</h1><fieldset><legend>Do you already have a domain name?</legend><div class="choices"><SelectCard v-for="x in ['Yes','No','Not sure']" :value="x" v-model="form.domain_status"/></div></fieldset><label v-if="form.domain_status==='Yes'">Domain name<input placeholder="example.com" v-model="form.domain"></label><fieldset><legend>Do you already have website hosting?</legend><div class="choices"><SelectCard v-for="x in ['Yes','No','Not sure']" :value="x" v-model="form.hosting_status"/></div></fieldset><div v-if="['No','Not sure'].includes(form.hosting_status)" class="info"><strong>Your first year of hosting is included.</strong><p>From year two, hosting starts at 1,500 THB/year for websites using up to 5GB storage.</p></div><fieldset v-if="['No','Not sure'].includes(form.hosting_status)"><legend>Would you like us to provide hosting?</legend><div class="choices"><SelectCard v-for="x in ['Yes','I already have hosting',`I'd like to discuss this first`]" :value="x" v-model="form.hosting_choice"/></div></fieldset><p class="privacy">For your security, never share passwords or hosting credentials in this form.</p></section>
<section v-if="current===6"><p class="eyebrow">Final details</p><h1>Almost done</h1><label>When would you like the website to be ready?<DatePicker v-model="form.target_launch" :disabled="form.no_date"/></label><label class="inline"><input type="checkbox" v-model="form.no_date"> No specific date</label><label>Is there anything else we should know about the project?<textarea rows="7" v-model="form.notes"></textarea></label><label class="honeypot" aria-hidden="true">Website<input tabindex="-1" autocomplete="off" v-model="form.website"></label></section>
<FormNavigation :first="current===0" @back="back" @next="next"/></div><section v-else class="review"><p class="eyebrow">Ready to send</p><h1>Review your project details</h1><p class="lede">Check everything looks right before submitting.</p><div class="review-grid"><article v-for="(group,i) in [{t:'Business',v:[form.company_name,form.contact_name,form.email]},{t:'Website',v:[val(form.website_type),form.primary_action,`${form.language_count} language(s): ${val(form.languages)}`]},{t:'Pages',v:[val(form.pages),val(form.custom_pages),sitemapFile?`Sitemap: ${sitemapFile.name}`:'No sitemap uploaded']},{t:'Content & Assets',v:[form.content_status,val(form.assets),`${files.length} uploaded file(s)`]},{t:'Features',v:[val(form.features)]},{t:'Domain & Hosting',v:[form.domain_status,form.domain,form.hosting_status,form.hosting_choice]},{t:'Timeline',v:[form.no_date?'No specific date':form.target_launch,form.notes]}]"><header><h2>{{ group.t }}</h2><button type="button" @click="go(i)">Edit</button></header><p v-for="x in group.v" v-if="x">{{ x }}</p></article></div><p v-if="serverError" class="server-error">{{ serverError }}</p><FormNavigation :last="true" :submitting="submitting" @back="back" @next="submit"/></section></main></div></div></template>
